#include <bits/stdc++.h>
using namespace std;

constexpr int N = 50;
constexpr int M = 50;
constexpr int K = 50;
constexpr int T = N + K + 1;
constexpr int N_ = N * T + 1;
constexpr int M_ = K + (M * 2 * K + N) * (T - 1);
constexpr int INF = 0x3f3f3f3f;

struct Node {
	Node* next;
	int dest;
};

Node aa[N], aa_[N_];
Node* edgePool1 = nullptr;
Node* edgePool2 = nullptr;

int pi[N_], kk[N_], bb[N_];
int pq[1 + N_], iq[N_], cnt;

inline bool LT(int u, int v) {
	return pi[u] < pi[v] || (pi[u] == pi[v] && kk[u] < kk[v]);
}

int i2(int i) {
	i *= 2;
	return i > cnt ? 0 : (i < cnt && LT(pq[i + 1], pq[i]) ? i + 1 : i);
}

void pq_up(int u) {
	for (int i = iq[u], j; (j = i / 2) && LT(u, pq[j]); i = j)
		pq[iq[pq[j]] = i] = pq[j];
	pq[iq[u] = (int)(iq[u])] = u;
}

void pq_dn(int u) {
	for (int i = iq[u], j; (j = i2(i)) && LT(pq[j], u); i = j)
		pq[iq[pq[j]] = i] = pq[j];
	pq[iq[u] = (int)(iq[u])] = u;
}

void pq_add(int u) {
	iq[u] = ++cnt;
	pq_up(u);
}

int pq_remove_first() {
	int u = pq[1], v = pq[cnt--];
	iq[v] = 1;
	pq_dn(v);
	return u;
}

void add(int i, int j) {
	if (!edgePool1) {
		edgePool1 = new Node[M * 2 + 1];
		edgePool1 -= 1;
	}
	edgePool1->dest = j;
	edgePool1->next = aa[i].next;
	aa[i].next = edgePool1++;
}

void add_(int i, int h) {
	if (!edgePool2) {
		edgePool2 = new Node[M_ * 2 + 1];
		edgePool2 -= 1;
	}
	edgePool2->dest = h;
	edgePool2->next = aa_[i].next;
	aa_[i].next = edgePool2++;
}

int n_, m_;
int uu[M_], vv[M_], uv[M_], cost[M_], cost_[M_];
int cc[M_ * 2];

void link(int u, int v, int cap, int cos) {
	int h = m_++;
	uu[h] = u;
	vv[h] = v;
	uv[h] = u ^ v;
	cost[h] = cos;
	cc[h << 1 ^ 0] = cap;
	add_(u, h << 1 ^ 0);
	add_(v, h << 1 ^ 1);
}

void dijkstra(int s) {
	fill(pi, pi + n_, INF);
	pi[s] = 0;
	pq_add(s);
	while (cnt) {
		Node* l;
		int u = pq_remove_first(), v;
		int h, h_, p, k = kk[u] + 1;
		for (l = aa_[u].next; l; l = l->next) {
			if (cc[h_ = l->dest]) {
				h = h_ >> 1;
				p = pi[u] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);
				v = u ^ uv[h];
				if (pi[v] == INF) {
					pi[v] = p;
					kk[v] = k;
					bb[v] = h_;
					pq_add(v);
				} else if (pi[v] > p || (pi[v] == p && kk[v] > k)) {
					pi[v] = p;
					kk[v] = k;
					bb[v] = h_;
					pq_up(v);
				}
			}
		}
	}
}

void push(int s, int t) {
	int u, h, h_;
	for (u = t; u != s; u ^= uv[h]) {
		h = (h_ = bb[u]) >> 1;
		cc[h_]--;
		cc[h_ ^ 1]++;
	}
}

int edmonds_karp(int s, int t) {
	int c, h;
	memcpy(cost_, cost, m_ * sizeof *cost);
	while (1) {
		dijkstra(s);
		if (pi[t] == INF) break;
		push(s, t);
		for (h = 0; h < m_; h++) {
			int u = uu[h], v = vv[h];
			if (pi[u] != INF && pi[v] != INF)
				cost_[h] += pi[u] - pi[v];
		}
	}
	c = 0;
	for (h = 0; h < m_; h++)
		c += cost[h] * cc[h << 1 ^ 1];
	return c;
}

int main() {
	vector<int> ii(K);
	int n, m, k, t, c, d, h, i, j, s, u, v, x;
	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
	for (h = 0; h < k; h++) {
		scanf("%d", &ii[h]);
		ii[h]--;
	}
	while (m--) {
		scanf("%d%d", &i, &j);
		i--; j--;
		add(i, j); add(j, i);
	}
	t = n + k + 1;
	n_ = n * t + 1;
	m_ = 0;
	for (i = 0; i < n; i++)
		for (s = 0; s < t - 1; s++) {
			Node* l;
			u = i * t + s;
			for (l = aa[i].next; l; l = l->next) {
				j = l->dest;
				v = j * t + s + 1;
				for (x = 1; x <= k; x++)
					link(u, v, 1, c + (x * 2 - 1) * d);
			}
		}
	for (i = 0; i < n; i++)
		for (s = 0; s < t - 1; s++) {
			u = i * t + s; v = u + 1;
			link(u, v, k, i == 0 ? 0 : c);
		}
	for (h = 0; h < k; h++)
		link(n_ - 1, ii[h] * t + 0, 1, 0);
	printf("%d\n", edmonds_karp(n_ - 1, 0 * t + t - 1));
	return 0;
}
